	.file	"xpkDMCB_lib.s"
	.text

/*
**	xpkDMCB_lib.s -- resident module header for
**	xpkDMCB.library 1.1 "Dynamic Markov Compression"
**
**	Single code hunk, "moveq #-1,d0 / rts" entry stub,
**	RomTag (ver 1, NT_LIBRARY, AUTOINIT), InitTable
**	(dataSize 0x2a), word-offset FUNCTABLE generated by
**	genfunctab.py, LibInit requiring AFB_68020+AFB_68881,
**	then the static XpkInfo descriptor + XpkMode.
**
**	Hunk map of the original (offset -> contents):
**	  0x00  moveq #-1,d0 / rts    entry stub
**	  0x04  RomTag                AUTOINIT, ver 1
**	  0x1e  libname/idstr + strings
**	  0xd4  InitTable             dataSize 0x2a
**	  0xe8  datatab
**	  0xec  functab               -1, 10 word offsets, -1
**	  0x100 LibInit               AttnFlags 020+881 check
**	  0x120 LibOpen/Close/Expunge/null
**	  0x176 XpksPackerInfo        lea descriptor 0x4b2
**	  0x17e XpksPackChunk         DMC encoder
**	  0x292 XpksUnpackChunk       DMC decoder
**	  0x352 model update
**	  0x3b4 model init
**	  0x4b2 XpkInfo + XpkMode + strings
*/

	.globl	_start
_start:
	moveq	#-1,%d0
	rts

	.globl	_romtag
_romtag:
	.word	0x4afc
	.long	_romtag
	.long	_endmodule
	.byte	0x80			/* RTF_AUTOINIT		    */
	.byte	1			/* RT_VERSION = 1	    */
	.byte	9			/* NT_LIBRARY		    */
	.byte	0			/* RT_PRI		    */
	.long	_libname
	.long	_idstr
	.long	_inittab

	.globl	_inittab
_inittab:
	.long	0x2a			/* dataSize		    */
	.long	_functab
	.long	_datatab
	.long	_LibInit

_datatab:
	.byte	0xa0,0x0c		/* ln_Type = 9	    */
	.byte	0x09,0x00
	.byte	0x80,0x0a		/* ln_Name	    */
	.long	_libname
	.byte	0xa0,0x0e		/* lib_Flags = 6    */
	.byte	0x06,0x00
	.byte	0x90,0x14		/* version = 1	    */
	.word	0x0001
	.byte	0x90,0x16		/* revision = 0    */
	.word	0x0000
	.byte	0x80,0x18		/* idstring	    */
	.long	_idstr
	.byte	0x00,0x00

/*
**	LibInit -- refuse to load without 68020 + 68881.
**	a0 = seglist, d0 = libbase, a6 = execbase.
*/
	.globl	_LibInit
_LibInit:
	moveal	4.w,%a1
	btst	#1,%a1@(297)		/* AFB_68020		    */
	beq	_start
	btst	#4,%a1@(297)		/* AFB_68881		    */
	beq	_start
	moveal	%d0,%a1
	movel	%a0,%a1@(34)		/* seglist		    */
	rts

/* ------------------------------------------------------------------ */
/* static XpkInfo descriptor (XpksPackerInfo returns its address)	    */
/* ------------------------------------------------------------------ */

	.even
	.globl	_xpkinfo
_xpkinfo:
	.word	1			/* xi_XpkInfoVersion	    */
	.word	1			/* xi_LibVersion	    */
	.word	2			/* xi_MasterVersion	    */
	.word	0			/* xi_ModesVersion	    */
	.long	_s_dmcb			/* xi_Name		    */
	.long	_s_longname		/* xi_LongName		    */
	.long	_s_basedesc		/* xi_Description	    */
	.long	0x444d4342		/* xi_ID = 'DMCB'	    */
	.long	9			/* xi_Flags PK+UP_CHUNK	    */
	.long	0x28000			/* xi_MaxPkInChunk	    */
	.long	100			/* xi_MinPkInChunk	    */
	.long	0x28000			/* xi_DefPkInChunk	    */
	.long	_s_compressing		/* xi_PackMsg		    */
	.long	_s_expanding		/* xi_UnpackMsg		    */
	.long	_s_compressed		/* xi_PackedMsg		    */
	.long	_s_expanded		/* xi_UnpackedMsg	    */
	.word	100			/* xi_DefMode		    */
	.word	0			/* xi_Pad		    */
	.long	_s_xpkmode		/* xi_ModeDesc		    */
	.long	0,0,0,0,0,0		/* xi_Reserved		    */

/* XpkMode (42 bytes): memory fields are in KB here
 * (0x800 KB = 2 MB workmem)					    */
_s_xpkmode:
	.long	0			/* xm_Next		    */
	.long	100			/* xm_Upto		    */
	.long	1			/* xm_Flags		    */
	.long	0x800			/* xm_PackMemory 2048 KB    */
	.long	0x800			/* xm_UnpackMemory 2048 KB  */
	.long	7			/* xm_PackSpeed	    */
	.long	7			/* xm_UnpackSpeed	    */
	.word	0x01bd			/* xm_Ratio = 445	    */
	.word	0			/* xm_ChunkSize	    */
	.ascii	"normal"
	.byte	0,0,0,0

_s_dmcb:
	.ascii	"DMCB"
	.byte	0
_s_longname:
	.ascii	"Dynamic Markov Compression v1.1"
	.byte	0
_s_basedesc:
	.ascii	"Arithmetic coding using dynamic Markovmodelling"
	.byte	0
_s_compressing:
	.ascii	"Compressing"
	.byte	0
_s_expanding:
	.ascii	"Expanding"
	.byte	0
_s_compressed:
	.ascii	"Compressed"
	.byte	0
_s_expanded:
	.ascii	"Expanded"
	.byte	0

	.even
_libname:
	.ascii	"xpkDMCB.library"
	.byte	0
_idstr:
	.ascii	"xpkDMCB v1.1"
	.byte	13,10,0
